```latex
\documentclass[12pt]{article}
\usepackage{geometry}
\usepackage{amsmath,amssymb}
\geometry{margin=1in}

\begin{document}

\title{SAT.O$_{10}$ Two-Sector Calibration Module}
\author{Generated by SAT.4D Pipeline}
\date{\today}
\maketitle

\section*{Overview}
This module implements the two-sector calibration and prediction utilities for the SAT.O$_{10}$ string-winding framework.  It provides:
\begin{itemize}
  \item Leptonic and hadronic ground-state fits (\(\,m^2 = p_2\,Q^2 + p_1\)).
  \item Radial excitation predictions via an additional constant \(k_{\rm rad}\).
  \item Plotting routines to overlay theoretical trajectories and data.
\end{itemize}

\section{Functions}

\subsection{Leptonic Calibration}
\begin{verbatim}
def calibrate_leptonic(masses, Q_vals) -> dict
\end{verbatim}
Fits 
\[
  m^2 = p_2\,Q^2 + p_1
\]
to a list of lepton masses (e.g.\ \(e,\mu,\pi\)) and windings \(Q\), returning
\(\{p_2,p_1\}\).

\subsection{Hadronic Calibration}
\begin{verbatim}
def calibrate_hadronic(masses, Q_vals) -> dict
\end{verbatim}
Same form as leptonic, but applied to hadronic resonances (e.g.\ \(\rho, K^*,\phi\)).

\subsection{Ground-State Prediction}
\begin{verbatim}
def predict_ground_states(p2, p1, Q_range) -> pandas.DataFrame
\end{verbatim}
For each \(Q\) in \texttt{Q\_range}, computes 
\[
  m_{\rm ground}(Q)=\sqrt{p_2\,Q^2 + p_1}\,,
\]
filtering out tachyonic cases.

\subsection{Radial Excitations}
\begin{verbatim}
def predict_radial_states(p2, p1, k_rad, Q_vals) -> pandas.DataFrame
\end{verbatim}
Adds a constant radial shift \(k_{\rm rad}\) (fitted from an \(N=2\) state) to predict first excited masses:
\[
  m_{\rm radial}(Q)=\sqrt{p_2\,Q^2 + p_1 + k_{\rm rad}}\,.
\]

\subsection{Trajectory Plotting}
\begin{verbatim}
def plot_trajectories(params_lept, params_had)
\end{verbatim}
Draws \(m^2\) versus \(Q\) for both sectors, marking the input data points.

\section{Usage Example}
\begin{verbatim}
from sat_o10_two_sector import (
    calibrate_leptonic,
    calibrate_hadronic,
    predict_ground_states,
    predict_radial_states,
    plot_trajectories,
)

# Lepton fit:
lep_params = calibrate_leptonic([0.000511,0.10566,0.13957],[1,2,3])

# Hadron fit:
had_params = calibrate_hadronic([0.775,0.892,1.019],[3,4,6])

# Predict ground states for Q=1..10:
df_lep = predict_ground_states(**lep_params, Q_range=range(1,11))
df_had = predict_ground_states(**had_params, Q_range=range(3,11))

# Fit radial slope k_rad from ρ(1450):
k_rad = 1.450**2 - (had_params['p2']*3**2 + had_params['p1'])
df_rad = predict_radial_states(**had_params, k_rad=k_rad, Q_vals=[3,4,6])

# Plot trajectories:
plot_trajectories(
    dict(params_lept, masses=[0.000511,0.10566,0.13957], Q_vals=[1,2,3]),
    dict(params_had, masses=[0.775,0.892,1.019], Q_vals=[3,4,6])
)
\end{verbatim}

\end{document}
```

