\begin{itemize}
  \item Mass formula: $m^2 = k\,(N + \beta\,Q^2 - a)$
  \item Spectrum generation over ranges of $(N,Q)$
  \item Ground–state calibration from $N=0$ data
\end{itemize}

\subsection*{Functions}

