latex_o9 = r"""\documentclass[12pt]{article}
\usepackage{geometry}
\usepackage{amsmath,amssymb}
\geometry{margin=1in}

\begin{document}

\title{Module SAT.O$_9$ (\texttt{sat\_o9.py})}
\author{SAT.4D Coherence Project}
\date{\today}
\maketitle

\section*{Overview}
Implements the 4D-only string embedding computations:
\begin{itemize}
  \item Mass formula: \(m^2 = k\,(N + \beta\,Q^2 - a)\)
  \item Spectrum generation over ranges of \((N,Q)\)
  \item Ground–state calibration from \(N=0\) data
\end{itemize}

\section{Functions}

\subsection{\texttt{mass\_squared}}
\begin{verbatim}
def mass_squared(N, Q, k, beta, a):
    """
    Compute m^2 = k*(N + beta*Q^2 - a).
    """
\end{verbatim}

\subsection{\texttt{mass\_spectrum}}
\begin{verbatim}
def mass_spectrum(N_range, Q_range, k, beta, a):
    """
    Return a DataFrame listing m^2 for each (N, Q).
    """
\end{verbatim}

\subsection{\texttt{calibrate\_from\_ground\_states}}
\begin{verbatim}
def calibrate_from_ground_states(masses, Q_vals, a_fixed=1.0):
    """
    Fit k and beta from N=0 ground-state masses.
    Solves m_i^2 = k*(beta*Q_i^2 - a_fixed) for inputs
    masses[i], Q_vals[i].
    Returns {'k':..., 'beta':..., 'a': a_fixed}.
    """
\end{verbatim}

\section*{Usage Example}
\begin{verbatim}
from sat_o.sat_o9 import calibrate_from_ground_states, mass_spectrum

# Calibrate from electron, muon, pion (N=0, Q=1,2,3)
params = calibrate_from_ground_states(
    masses=[0.000511, 0.10566, 0.13957],
    Q_vals=[1,2,3],
    a_fixed=1.0
)
# Generate the (N=0..5, Q=1..5) spectrum
df = mass_spectrum(N_range=range(6), Q_range=range(1,6),
                   k=params['k'], beta=params['beta'], a=params['a'])
\end{verbatim}

\end{document}
"""

# LaTeX content for sat_o10_module.tex
latex_o10 = r"""\documentclass[12pt]{article}
\usepackage{geometry}
\usepackage{amsmath,amssymb}
\usepackage{graphicx}
\geometry{margin=1in}

\begin{document}

\title{Module SAT.O$_{10}$ (\texttt{sat\_o10.py})}
\author{SAT.4D Coherence Project}
\date{\today}
\maketitle

\section*{Overview}
Provides the two-sector calibration and prediction framework:
\begin{itemize}
  \item \emph{Leptonic sector}: fit \(m^2 = p_2\,Q^2 + p_1\) to \((e,\mu,\pi)\)
  \item \emph{Hadronic sector}: fit the same form to \((\rho,K^*,\phi)\)
  \item Predict ground states and radial excitations
  \item Plot trajectories with data overlays
\end{itemize}

\section{Functions}

\subsection{\texttt{calibrate\_leptonic}}
\begin{verbatim}
def calibrate_leptonic(masses, Q_vals):
    """
    Fit m^2 = p2*Q^2 + p1 to leptonic ground states.
    Returns {'p2':..., 'p1':..., 'masses':..., 'Q_vals':...}.
    """
\end{verbatim}

\subsection{\texttt{calibrate\_hadronic}}
\begin{verbatim}
def calibrate_hadronic(masses, Q_vals):
    """
    Fit m^2 = p2*Q^2 + p1 to hadronic ground states.
    Returns {'p2':..., 'p1':..., 'masses':..., 'Q_vals':...}.
    """
\end{verbatim}

\subsection{\texttt{predict\_ground\_states}}
\begin{verbatim}
def predict_ground_states(p2, p1, Q_range):
    """
    Compute m_ground(Q)=sqrt(p2*Q^2 + p1) for Q in Q_range.
    """
\end{verbatim}

\subsection{\texttt{predict\_radial\_states}}
\begin{verbatim}
def predict_radial_states(p2, p1, k_rad, Q_vals):
    """
    Compute m_radial(Q)=sqrt(p2*Q^2 + p1 + k_rad) for Q in Q_vals.
    """
\end{verbatim}

\subsection{\texttt{plot\_trajectories}}
\begin{verbatim}
def plot_trajectories(params_lept, params_had):
    """
    Plot m^2 vs Q for both sectors, with input data points.
    """
\end{verbatim}

\section*{Usage Example}
\begin{verbatim}
from sat_o.sat_o10 import (
    calibrate_leptonic, calibrate_hadronic,
    predict_ground_states, predict_radial_states,
    plot_trajectories
)

# 1. Calibrate each sector
lep_params = calibrate_leptonic(
    masses=[0.000511,0.10566,0.13957], Q_vals=[1,2,3]
)
had_params = calibrate_hadronic(
    masses=[0.775,0.892,1.019], Q_vals=[3,4,6]
)

# 2. Predict ground states for Q=1..10
df_lep = predict_ground_states(**lep_params, Q_range=range(1,11))
df_had = predict_ground_states(**had_params, Q_range=range(3,11))

# 3. Fit radial slope from ρ(1450)
k_rad = 1.450**2 - (had_params['p2']*3**2 + had_params['p1'])
df_rad = predict_radial_states(**had_params, k_rad=k_rad, Q_vals=[3,4,6])

# 4. Plot both trajectories
plot_trajectories(lep_params, had_params)
\end{verbatim}

\end{document}
"""

# Write files
with open('/mnt/data/sat_o9_module.tex', 'w') as f:
    f.write(latex_o9)

with open('/mnt/data/sat_o10_module.tex', 'w') as f:
    f.write(latex_o10)

